ErrorStatus HSEStartUpStatus;

/* 1. 开启 HSE */
RCC_HSEConfig(RCC_HSE_ON);

/* 2. 必须等待起振成功，否则后面全部白配 */
HSEStartUpStatus = RCC_WaitForHSEStartUp();
if (HSEStartUpStatus == SUCCESS)
{
  /* 3. HSE 就绪，继续配置 PLL */
}
else
{
  /* HSE 起振失败，芯片会退回 HSI 8MHz */
}

RCC_HSEConfig(RCC_HSE_ON);

if (RCC_WaitForHSEStartUp() == SUCCESS)
{
  /* 晶振正常，可以配 PLL 到 72MHz */
  RCC_PLLConfig(RCC_PLLSource_HSE_Div1, RCC_PLLMul_9);
}
else
{
  /* 晶振异常：检查焊接、负载电容、晶振频率 */
  while (1);
}

/* 8MHz HSE × 9 = 72MHz */
RCC_PLLConfig(RCC_PLLSource_HSE_Div1, RCC_PLLMul_9);

/* 使能 PLL 并等待锁定 */
RCC_PLLCmd(ENABLE);
while (RCC_GetFlagStatus(RCC_FLAG_PLLRDY) == RESET);

/* 切换系统时钟到 PLL */
RCC_SYSCLKConfig(RCC_SYSCLKSource_PLLCLK);
while (RCC_GetSYSCLKSource() != 0x08);   /* 0x08 表示当前是 PLL */

RCC_PLLCmd(ENABLE);

/* 等待 PLL 锁定，锁定后才能作为系统时钟 */
while (RCC_GetFlagStatus(RCC_FLAG_PLLRDY) == RESET)
{
}

/* 切到 PLL（72MHz） */
RCC_SYSCLKConfig(RCC_SYSCLKSource_PLLCLK);

/* 必须确认切换完成，否则后续外设时钟全错 */
while (RCC_GetSYSCLKSource() != 0x08)
{
}

/* 确认系统时钟已切到 PLL */
if (RCC_GetSYSCLKSource() == 0x08)
{
  /* 当前运行在 PLL 输出 */
}

/* 开启时钟安全系统与其中断 */
RCC_ClockSecuritySystemCmd(ENABLE);
RCC_ITConfig(RCC_IT_CSS, ENABLE);

/* NVIC 里还要使能 RCC_IRQn */

/* 72MHz PLL → 48MHz USB 时钟 */
RCC_USBCLKConfig(RCC_USBCLKSource_PLLCLK_1Div5);

/* 还要使能 USB 外设时钟 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_USB, ENABLE);

/* PCLK2 = 72MHz，6 分频得 12MHz（≤14MHz） */
RCC_ADCCLKConfig(RCC_PCLK2_Div6);

/* 再使能 ADC1 时钟 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1, ENABLE);

/* 开 PWR/BKP 时钟，解除备份域写保护 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

/* 开启 LSE */
RCC_LSEConfig(RCC_LSE_ON);

/* LSE 起振慢，必须等待，可能要 1~2 秒 */
while (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET)
{
}

/* 开启 LSI 并等待就绪 */
RCC_LSICmd(ENABLE);
while (RCC_GetFlagStatus(RCC_FLAG_LSIRDY) == RESET)
{
}

/* 用 LSE 作为 RTC 时钟源 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

RCC_LSEConfig(RCC_LSE_ON);
while (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET);

RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);
RCC_RTCCLKCmd(ENABLE);

RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);
RCC_RTCCLKCmd(ENABLE);

/* 之后才能配置 RTC */
RTC_SetPrescaler(32767);   /* 32768Hz / 32768 = 1Hz */

RCC_ClocksTypeDef RCC_Clocks;

RCC_GetClocksFreq(&RCC_Clocks);

/* 标准 72MHz 配置下应为：
   SYSCLK=72000000  HCLK=72000000
   PCLK1 =36000000  PCLK2=72000000  ADCCLK=12000000 */

/* 一次开多个外设时钟，用按位或 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_GPIOB |
                       RCC_APB2Periph_AFIO, ENABLE);

/* 串口 1 也挂 APB2 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1, ENABLE);

/* 用串口 2 与定时器 3，都在 APB1 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_USART2 | RCC_APB1Periph_TIM3, ENABLE);

/* 用 RTC 或 BKP 时，PWR 与 BKP 时钟都要开 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);

/* 复位 DMA1：先拉高再释放 */
RCC_AHBPeriphResetCmd(RCC_AHBPeriph_DMA1, ENABLE);
RCC_AHBPeriphResetCmd(RCC_AHBPeriph_DMA1, DISABLE);

/* GPIO_DeInit 内部就是这么做的 */
RCC_APB2PeriphResetCmd(RCC_APB2Periph_GPIOA, ENABLE);
RCC_APB2PeriphResetCmd(RCC_APB2Periph_GPIOA, DISABLE);

/* 复位 USART2 */
RCC_APB1PeriphResetCmd(RCC_APB1Periph_USART2, ENABLE);
RCC_APB1PeriphResetCmd(RCC_APB1Periph_USART2, DISABLE);

RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

/* 清空备份域（RTC 与备份寄存器都会丢） */
RCC_BackupResetCmd(ENABLE);
RCC_BackupResetCmd(DISABLE);

/* 开启 CSS，HSE 失效时自动切到 HSI */
RCC_ClockSecuritySystemCmd(ENABLE);

/* 如需中断处理 */
RCC_ITConfig(RCC_IT_CSS, ENABLE);
/* NVIC 里还要使能 RCC_IRQn */

GPIO_InitTypeDef GPIO_InitStructure;

RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);

GPIO_InitStructure.GPIO_Pin = GPIO_Pin_8;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 输出 HSE，PA8 上应测到 8MHz */
RCC_MCOConfig(RCC_MCO_HSE);

/* 等待 PLL 锁定 */
RCC_PLLCmd(ENABLE);
while (RCC_GetFlagStatus(RCC_FLAG_PLLRDY) == RESET)
{
}

void RCC_IRQHandler(void)
{
  /* CSS 中断：HSE 失效 */
  if (RCC_GetITStatus(RCC_IT_CSS) != RESET)
  {
    /* 紧急处理：重新配置时钟、关闭危险外设 */
    RCC_ClearITPendingBit(RCC_IT_CSS);
  }
}

void RCC_IRQHandler(void)
{
  if (RCC_GetITStatus(RCC_IT_CSS) != RESET)
  {
    /* 处理... */
    RCC_ClearITPendingBit(RCC_IT_CSS);   /* 必须清 */
  }
}
